cd D:/Repos/angular-jig && python3 - <<'EOF'
p='src/app/hero-detail/hero-detail.view-model.ts'
s=open(p).read()
s=s.replace("    submission: { action: () => this.saveEdits() },","    submission: {\n      action: async () => {\n        this.saveEdits();\n        return undefined;\n      },\n    },")
s=s.replace("  private saveEdits(): undefined {\n    const changes = heroSchema.parse(this._model());\n    this._heroes.update(this.heroId(), changes);\n    this.saved.set(true);\n    return undefined;\n  }",
"""  // A select reports null when it is cleared. Keep the current choice in that case.
  public choose<K extends SelectField>(field: K, value: HeroModel[K] | null | undefined): void {
    if (!value) return;

    this._model.update((model) => ({ ...model, [field]: value }));
  }

  private saveEdits(): void {
    const changes = heroSchema.parse(this._model());
    this._heroes.update(this.heroId(), changes);
    this.saved.set(true);
  }""")
s=s.replace("// Hero detail state and logic.","type SelectField = 'powerClass' | 'status' | 'clearance';\n\n// Hero detail state and logic.")
open(p,'w').write(s)

p='src/app/hero-detail/hero-detail.html'
s=open(p).read()
s=s.replace('(valueChange)="vm.form.powerClass().value.set($event)"','(valueChange)="vm.choose(\'powerClass\', $event)"')
s=s.replace('(valueChange)="vm.form.status().value.set($event)"','(valueChange)="vm.choose(\'status\', $event)"')
s=s.replace('(valueChange)="vm.form.clearance().value.set($event)"','(valueChange)="vm.choose(\'clearance\', $event)"')
open(p,'w').write(s)
EOF
